var e={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:`ホットエンドが維持できる最大の容積流量 (mm³/s) を測定します。流量を上げながらエクストルーダーの StallGuard 負荷を監視し、ギアが滑る瞬間を捉えます。まずプランをプレビューしてください。ライブテストは加熱して押し出すため、実行前にプリンターを準備しておきましょう。`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`ヘルプ`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`最大流量について`}},close:{t:0,b:{t:2,i:[{t:3}],s:`閉じる`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`使い方`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`テスト温度とフィラメント径を設定します (ホットエンドを選ぶと自動入力されます)。`}},{t:0,b:{t:2,i:[{t:3}],s:`プランをプレビューします。各流量ステップと押し出すフィラメント量が表示されます。`}},{t:0,b:{t:2,i:[{t:3}],s:`安全チェックリストにチェックを入れ、ライブテストを実行します (加熱 + 押し出し)。`}},{t:0,b:{t:2,i:[{t:3}],s:`維持できる最大流量を確認し、推奨スライサー値をコピーします。`}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:`テストの仕組み`}},body:{t:0,b:{t:2,i:[{t:3}],s:`エクストルーダーは容積流量を一定のペースで上げながらフィラメントを押し出します。ホブドギアがしっかり噛んでいる間は StallGuard の負荷値が安定していますが、滑り始めると値が大きくばらつきます。そのばらつき直前に達した最大流量が、維持可能な最大流量です。滑りを検知した時点でランプは止まるため、最初の滑り以降にフィラメントが削られることはありません。`}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard による滑り検知`}},body:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard はモーター負荷を報告する TMC ドライバーの機能です。このテストでは各流量ステップで何度もサンプリングし、ばらつき (IQR) や変動 (CV) の急上昇を探します。これがギアの噛み外れの兆候です。しきい値はドライバーごとのプロファイルに基づきます。注意: TMC2209 エクストルーダーでは実験的な SG4 経路を使うため、最初の実行はキャリブレーションとして扱ってください。`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`安全`}},body:{t:0,b:{t:2,i:[{t:3}],s:`これは高温で動作し、意図的にエクストルーダーを滑らせるテストです。フィラメントをロードし、ノズルの先がふさがれていないこと (ベッド上または捨て吐き出し用エリア) を確認し、そばを離れないでください。プリンターが印刷中は実行が拒否され、終了時には必ずヒーターがオフになります。`}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:`結果の活用`}},body:{t:0,b:{t:2,i:[{t:3}],s:`推奨値をスライサーの「最大容積速度」(フィラメントごと) に設定します。控えめな値 (測定最大値の 80%) は日常使いに安全な上限です。バランス値 (90%) はもう少し攻めた設定です。ホットエンド温度を上げると、通常は到達できる流量も上がります。`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`用語集`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:`容積流量`}},def:{t:0,b:{t:2,i:[{t:3}],s:`ホットエンドが 1 秒間に溶かせる樹脂量 (mm³/s)。高速印刷の本当の速度上限です。`}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},def:{t:0,b:{t:2,i:[{t:3}],s:`モーターの機械的負荷を報告する TMC ドライバーの信号。ここではエクストルーダーの滑りを検知するために使います。`}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:`滑り`}},def:{t:0,b:{t:2,i:[{t:3}],s:`エクストルーダーのギアがフィラメントを十分な速さでつかめなくなり、空回りする状態。流量の上限です。`}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:`メルトゾーン`}},def:{t:0,b:{t:2,i:[{t:3}],s:`ホットエンドの加熱される長さ。メルトゾーンが長いほど (例: Volcano) より高い流量を維持できます。`}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:`テストパラメーター`}},temperature:{t:0,b:{t:2,i:[{t:3}],s:`温度 (°C)`}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:`フィラメント径 Ø (mm)`}},hotend:{t:0,b:{t:2,i:[{t:3}],s:`ホットエンド (任意)`}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:`- なし -`}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:`予想 ~`},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:`開始流量 (mm³/s)`}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:`終了流量 (mm³/s)`}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:`ステップ (mm³/s)`}},samples:{t:0,b:{t:2,i:[{t:3}],s:`サンプル数 / ステップ`}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:`押し出し量 / ステップ (mm)`}},driver:{t:0,b:{t:2,i:[{t:3}],s:`エクストルーダードライバー`}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:`プリンターから検出`}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:`テスト用に StealthChop を自動で有効化`}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:`TMC2209/2240 のみ: StallGuard が読み取れるよう、一時的に stealthchop_threshold をエクストルーダーに書き込み、テスト後にコメントアウトします。printer.cfg を復元し、その都度ファームウェアを再起動します。`}},method:{t:0,b:{t:2,i:[{t:3}],s:`検出方法`}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:`Auto は StallGuard を使い、StallGuard が読み取れない場合はツールヘッドの加速度センサー (振動) にフォールバックします。加速度センサー方式は実験的です。`}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:`自動`}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},accel:{t:0,b:{t:2,i:[{t:3}],s:`加速度センサー`}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:`プランをプレビュー`}},title:{t:0,b:{t:2,i:[{t:3}],s:`計画されたランプ`}},stepCount:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` ステップ`}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:`mm`},{t:3,v:` mm のフィラメント`}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:`StallGuard フィールド: `},{t:4,k:`field`}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:`このドライバーで使える StallGuard フィールドがありません`}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:`流量 (mm³/s)`}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:`送り速度 (mm/min)`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`ライブテストはホットエンドを加熱し、意図的に滑るまでフィラメントを押し出します。これはプレビューのみで、まだ何も実行されません。`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`実行前 - 安全チェックリスト`}},items:[{t:0,b:{t:2,i:[{t:3}],s:`フィラメントがロードされ、スムーズに供給される。`}},{t:0,b:{t:2,i:[{t:3}],s:`ノズルの先がふさがれていない (空中の部品上ではなく、ベッド上または捨て箱の上)。`}},{t:0,b:{t:2,i:[{t:3}],s:`意図的にフィラメントが削れる/滑ることを了解している。`}},{t:0,b:{t:2,i:[{t:3}],s:`テスト中はプリンターのそばを離れない。`}}],ack:{t:0,b:{t:2,i:[{t:3}],s:`上記をすべて完了し、プリンターの準備ができました`}},note:{t:0,b:{t:2,i:[{t:3}],s:`印刷中は実行が拒否されます。終了時にヒーターは自動でオフになります。`}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:`ライブテストを実行`}},running:{t:0,b:{t:2,i:[{t:3}],s:`実行中… (加熱 + 押し出し)`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`ライブ最大流量テストを開始しますか?`}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:`ホットエンドを `},{t:4,k:`temp`},{t:3,v:` °C まで加熱し、エクストルーダーが滑るまで流量を上げながら、最大 `},{t:4,k:`mm`},{t:3,v:` mm のフィラメントを押し出します。`}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`今すぐ実行`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`キャンセル`}},busy:{t:0,b:{t:2,i:[{t:3}],s:`拒否: プリンターがビジー状態です (印刷中または一時停止中)。アイドル状態になってから再試行してください。`}},error:{t:0,b:{t:2,i:[{t:3}],s:`テストに失敗しました。`}},noSg:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard サンプルが読み取れませんでした。滑りの結果は信頼できない可能性があります。このモデル向けにドライバーのライブ SG フィールドの調整が必要と思われます。`}},progress:{t:0,b:{t:2,i:[{t:3,v:`ステップ `},{t:4,k:`step`},{t:3,v:`/`},{t:4,k:`total`},{t:3,v:` - `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:`加熱 / 開始中…`}},abort:{t:0,b:{t:2,i:[{t:3}],s:`実行を中止`}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:`中止中…`}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:`実行を中止しました - ヒーターはオフになりました。`}},reattached:{t:0,b:{t:2,i:[{t:3}],s:`再接続: この結果はページを離れている間に完了しました。`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`最大流量の実行に失敗しました。`}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:`中止すると常にヒーターがオフになります。`}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:`加熱前に、プリンターはホーミング (必要な場合) を行い、はっきり見えるようノズルを中央に移動します。`}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:`StealthChop を有効化中…`}},homing:{t:0,b:{t:2,i:[{t:3}],s:`プリンターをホーミング中…`}},centering:{t:0,b:{t:2,i:[{t:3}],s:`ノズルを中央に移動中…`}},heating:{t:0,b:{t:2,i:[{t:3}],s:`ホットエンドを加熱中…`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard 信号を確認中…`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`流量を上げています…`}},reverting:{t:0,b:{t:2,i:[{t:3}],s:`設定を復元中…`}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:`ホーム`}},center:{t:0,b:{t:2,i:[{t:3}],s:`中央`}},heat:{t:0,b:{t:2,i:[{t:3}],s:`加熱`}},check:{t:0,b:{t:2,i:[{t:3}],s:`確認`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`ランプ`}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:`ライブカメラ`}},live:{t:0,b:{t:2,i:[{t:3}],s:`LIVE`}},error:{t:0,b:{t:2,i:[{t:3}],s:`カメラを利用できません。`}},willShow:{t:0,b:{t:2,i:[{t:3}],s:`テスト中、ライブカメラ映像にノズルが表示されます。`}},minimize:{t:0,b:{t:2,i:[{t:3}],s:`最小化`}},maximize:{t:0,b:{t:2,i:[{t:3}],s:`最大化`}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:`拡大`}},shrink:{t:0,b:{t:2,i:[{t:3}],s:`縮小`}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:`結果`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`維持可能な最大流量`}},slipAt:{t:0,b:{t:2,i:[{t:4,k:`flow`},{t:3,v:` mm³/s で滑りを検知`}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:`テストした最高流量まで滑りなし`}},reason:{t:0,b:{t:2,i:[{t:3}],s:`詳細`}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:`推奨スライサー値 (最大容積速度)`}},conservative:{t:0,b:{t:2,i:[{t:3}],s:`控えめ (80%)`}},balanced:{t:0,b:{t:2,i:[{t:3}],s:`バランス (90%)`}},units:{t:0,b:{t:2,i:[{t:3}],s:`mm³/s`}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:`以前 (`},{t:4,k:`at`},{t:3,v:`) に測定した値です。最新の数値を得るには再実行してください。`}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:`信頼性低 - StallGuard 信号なし`}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:`到達したが未確認`}},via:{t:0,b:{t:2,i:[{t:4,k:`method`},{t:3,v:` で測定`}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:`振動 (加速度センサー) で測定 - 実験的です。数値は正確な上限ではなく目安として扱ってください。`}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:`ホットエンドを読み込み中…`}}}}};export{e as default};